parameters.jsCode:
let raw = $input.all()[0]?.json?.output || $input.all()[0]?.json?.text || $input.all()[0]?.json;

if (typeof raw === 'string') {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    return [{ json: JSON.parse(cleaned) }];
  } catch (e) {
    return [{ json: { status: 'success', summary: raw, reminders: [] } }];
  }
} else if (typeof raw === 'object' && raw !== null) {
  return [{ json: raw }];
}

return [{ json: { status: 'error', error_message: 'Empty response from agent' } }];
